SELECT t.execution_reason, COUNT(DISTINCT p.id) AS n, SUM(p.realized_pnl < 0) AS losers, SUM(p.status='STOPPED') AS stopped, ROUND(SUM(p.realized_pnl),4) AS pnl_gross FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_trade t ON t.signal_id = p.signal_id AND t.side = 'BUY' AND t.status = 'EXECUTED' WHERE p.closed_at IS NOT NULL GROUP BY t.execution_reason ORDER BY pnl_gross LIMIT 30;